package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.extension.ToolInterceptor;
import io.github.diodeme.ji.extension.PromptContributor;
import io.github.diodeme.ji.extension.PromptAssembler;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.time.Clock;
import java.util.List;
import java.util.concurrent.ExecutorService;

/** Immutable assembly input implemented by the internal Core runtime. */
public record RuntimeConfiguration(
        ModelProvider provider,
        SessionRepository sessionRepository,
        List<ToolDefinition> tools,
        List<PromptContributor> promptContributors,
        PromptAssembler.TokenCounter promptTokenCounter,
        int promptTokenBudget,
        String promptLocale,
        CompactionPolicy compactionPolicy,
        PermissionDecider permissionDecider,
        ToolExecutionPolicy toolExecutionPolicy,
        List<ToolInterceptor> toolInterceptors,
        IdGenerator idGenerator,
        Clock clock,
        ExecutorService executor) {
    public RuntimeConfiguration {
        if (provider == null || sessionRepository == null || permissionDecider == null || toolExecutionPolicy == null
                || promptTokenCounter == null || promptLocale == null || promptLocale.isBlank()
                || compactionPolicy == null
                || idGenerator == null || clock == null || executor == null) {
            throw new IllegalArgumentException("runtime fields must not be null");
        }
        if (promptTokenBudget < 0) throw new IllegalArgumentException("promptTokenBudget must not be negative");
        tools = List.copyOf(tools);
        promptContributors = List.copyOf(promptContributors);
        toolInterceptors = List.copyOf(toolInterceptors);
    }

    @FunctionalInterface
    public interface IdGenerator {
        String next(String scope);
    }
}
